import pathlib,re
def extend_secure_path(existing,directory,inspect):
    def valid(value):
        return isinstance(value,str) and len(value)<=512 and bool(re.fullmatch(r"/[A-Za-z0-9_./-]*",value)) and str(pathlib.PurePosixPath(value))==value and ".." not in pathlib.PurePosixPath(value).parts
    if not isinstance(existing,str) or not existing or len(existing)>4096 or any(not valid(part) for part in existing.split(":")):raise ValueError("invalid existing secure_path")
    if not valid(directory) or directory=="/":raise ValueError("approved absolute tool directory required")
    path=pathlib.PurePosixPath(directory)
    for parent in [path,*path.parents]:
        info=inspect(str(parent))
        if not info["is_dir"] or info["symlink"] or info["uid"]!=0 or info["mode"]&0o022:raise PermissionError("directory or ancestor not trusted")
    if directory in existing.split(":"):return existing
    return existing+":"+directory
